css:
main { display: grid !important; grid-template-columns: minmax(0, 1fr) 260px !important; column-gap: 40px !important; align-items: start !important; overflow: visible !important; }
main > .pod { grid-column: 1 !important; grid-row: 1 !important; min-width: 0 !important; }
main .toc { grid-column: 2 !important; grid-row: 1 !important; float: none !important; margin: 0 !important; max-width: none !important; width: 260px !important; position: sticky !important; top: 60px !important; max-height: calc(100vh - 80px) !important; overflow-y: auto !important; }
